class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = []
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))
            if len(self.spy_closes) > 101:
                self.spy_closes.pop(0)

        if data.Bars.ContainsKey(aapl):
            aapl_close = float(data.Bars[aapl].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Bars[aapl].EndTime, aapl_close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) >= 101:
            previous_close = self.spy_closes[-2]
            current_close = self.spy_closes[-1]
            previous_sma = sum(self.spy_closes[-101:-1]) / 100.0
            current_sma = sum(self.spy_closes[-100:]) / 100.0

            if not self.Portfolio[spy].Invested:
                if previous_close <= previous_sma and current_close > current_sma:
                    quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // current_close)
                    if quantity > 0:
                        self.MarketOrder(spy, quantity)
            elif previous_close >= previous_sma and current_close < current_sma:
                self.Liquidate(spy)

        if self.aapl_rsi.IsReady:
            if not self.Portfolio[aapl].Invested:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // float(data.Bars[aapl].Close))
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
            elif float(self.aapl_rsi.Current.Value) > 60:
                self.Liquidate(aapl)

