class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Market-state inputs continue to consume every available ticker bar.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        # A missing bar for any subscription suppresses every rule for the day.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        self.EvaluateStrategyA(data.Bars[self.spy])
        self.EvaluateStrategyB(data.Bars[self.aapl])

    def EvaluateStrategyA(self, bar: TradeBar):
        if self.spy_closes.Count < 101:
            return

        today_close = float(bar.Close)
        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_close = self.spy_closes[1]
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        invested = self.Portfolio[self.spy].Invested

        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma
        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma

        if not invested and crossed_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value // today_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
        elif invested and crossed_below:
            self.Liquidate(self.spy)

    def EvaluateStrategyB(self, bar: TradeBar):
        if not self.aapl_rsi.IsReady or self.previous_aapl_close is None:
            return

        invested = self.Portfolio[self.aapl].Invested
        if not invested and self.aapl_red_streak >= 3:
            cash_to_invest = 20000.0
            available_cash = float(self.Portfolio.CashBook["USD"].Amount)
            if available_cash >= cash_to_invest:
                quantity = int(cash_to_invest // float(bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
        elif invested and float(self.aapl_rsi.Current.Value) > 60.0:
            self.Liquidate(self.aapl)

