class ParallelSpyAaplStrategy(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_sma = self.sma("SPY", 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            "AAPL", 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        # Each quantity records only the shares owned by its strategy lot.
        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close

        # Market-state history advances even on a day when rules must be skipped.
        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            if self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value

        if any(data.bars.get(self.symbols[ticker]) is None for ticker in self.tickers):
            return

        if (
            self.spy_sma.is_ready
            and previous_spy_close is not None
            and previous_spy_sma is not None
        ):
            spy_close = spy_bar.close
            spy_sma = self.spy_sma.current.value

            if self.strategy_a_quantity == 0:
                crossed_above = (
                    previous_spy_close <= previous_spy_sma and spy_close > spy_sma
                )
                if crossed_above:
                    quantity = self.calculate_order_quantity("SPY", 0.40)
                    if quantity > 0:
                        self.market_order("SPY", quantity)
                        self.strategy_a_quantity = quantity
            else:
                crossed_below = (
                    previous_spy_close >= previous_spy_sma and spy_close < spy_sma
                )
                if crossed_below:
                    self.market_order("SPY", -self.strategy_a_quantity)
                    self.strategy_a_quantity = 0

        if self.strategy_b_quantity == 0 and self.aapl_rsi.is_ready:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_bar.close)
                if quantity > 0:
                    self.market_order("AAPL", quantity)
                    self.strategy_b_quantity = quantity
        elif self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
            self.market_order("AAPL", -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

