class ParallelSpyAaplStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy_closes = RollingWindow[float](100)
        self.spy_previous_relation = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot_quantity = 0
        self.aapl_lot_quantity = 0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        spy_relation = None
        if spy_bar is not None:
            self.spy_closes.Add(float(spy_bar.Close))
            if self.spy_closes.IsReady:
                sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
                spy_relation = float(spy_bar.Close) - sma

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        all_rules_ready = (
            self.spy_closes.IsReady
            and self.spy_previous_relation is not None
            and self.aapl_rsi.IsReady
            and self.aapl_previous_close is not None
        )

        if all_bars_present and all_rules_ready:
            if spy_relation is not None and self.spy_previous_relation is not None:
                if self.spy_lot_quantity == 0 and self.spy_previous_relation <= 0 < spy_relation:
                    quantity = self.CalculateOrderQuantity(spy, 0.40)
                    if quantity > 0:
                        self.MarketOrder(spy, quantity)
                        self.spy_lot_quantity = quantity
                elif self.spy_lot_quantity > 0 and self.spy_previous_relation >= 0 > spy_relation:
                    self.MarketOrder(spy, -self.spy_lot_quantity)
                    self.spy_lot_quantity = 0

            if self.aapl_lot_quantity == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // float(aapl_bar.Close))
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.aapl_lot_quantity = quantity
            elif (
                self.aapl_lot_quantity > 0
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(aapl, -self.aapl_lot_quantity)
                self.aapl_lot_quantity = 0

        if spy_relation is not None:
            self.spy_previous_relation = spy_relation

