        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot_open = False
        self.aapl_lot_open = False

    def OnData(self, data: Slice):
        spy_bar = (
            data.Bars[self.symbols["SPY"]]
            if data.Bars.ContainsKey(self.symbols["SPY"])
            else None
        )
        aapl_bar = (
            data.Bars[self.symbols["AAPL"]]
            if data.Bars.ContainsKey(self.symbols["AAPL"])
            else None
        )

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            self._evaluate_spy_strategy(
                spy_bar.Close, previous_spy_close, previous_spy_sma
            )
            self._evaluate_aapl_strategy(aapl_bar.Close)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _evaluate_spy_strategy(
        self, close, previous_close, previous_sma
    ):
        if (
            not self.spy_sma.IsReady
            or previous_close is None
            or previous_sma is None
        ):
            return

        current_sma = self.spy_sma.Current.Value
        crossed_above = previous_close <= previous_sma and close > current_sma
        crossed_below = previous_close >= previous_sma and close < current_sma

        if self.spy_lot_open:
            if crossed_below:
                self.Liquidate(self.symbols["SPY"])
                self.spy_lot_open = False
        elif crossed_above:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot_open = True

    def _evaluate_aapl_strategy(self, close):
        if not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot_open:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.aapl_lot_open = False
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 // close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot_open = True

