        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.set_warm_up(100, Resolution.DAILY)

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.spy)
        aapl_bar = data.bars.get(self.aapl)

        current_spy_close = float(spy_bar.close) if spy_bar is not None else None
        current_spy_sma = float(self.spy_sma.current.value) if self.spy_sma.is_ready else None

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.close)
            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = current_aapl_close

        all_bars_present = all(data.bars.get(symbol) is not None for symbol in self.required_symbols)

        if all_bars_present and not self.is_warming_up:
            self._run_spy_strategy(current_spy_close, current_spy_sma)
            self._run_aapl_strategy(float(aapl_bar.close))

        if current_spy_close is not None and current_spy_sma is not None:
            self.previous_spy_close = current_spy_close
            self.previous_spy_sma = current_spy_sma

