        cash_to_invest = 20_000
        if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= cash_to_invest:
            quantity = floor(cash_to_invest / close)
            if quantity > 0:
                self.market_order(self.aapl, quantity)

