            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(data.Bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        spy = self.symbols["SPY"]
        if not self.spy_order_pending:
            if self.Portfolio[spy].Invested:
                if spy_crossed_below:
                    self.spy_order_pending = True
                    self.Liquidate(spy, "Strategy A: close crossed below SMA100")
            elif spy_crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity != 0:
                    self.spy_order_pending = True
                    self.MarketOrder(spy, quantity, tag="Strategy A: close crossed above SMA100")

        aapl = self.symbols["AAPL"]
        if self.aapl_rsi.IsReady and not self.aapl_order_pending:
            if self.Portfolio[aapl].Invested:
                if self.aapl_rsi.Current.Value > 60:
                    self.aapl_order_pending = True
                    self.Liquidate(aapl, "Strategy B: RSI14 above 60")
            elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(aapl, quantity, tag="Strategy B: three red days")

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            return

        if order_event.Symbol == self.symbols["SPY"]:
            self.spy_order_pending = False
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.aapl_order_pending = False

