class DailyIndependentStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.rsi_change_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

    def on_data(self, data: Slice):
        bars = {
            ticker: data.bars.get(symbol)
            for ticker, symbol in self.symbols.items()
        }

        spy_bar = bars["SPY"]
        spy_sma = None
        if spy_bar is not None:
            spy_close = float(spy_bar.close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0

        aapl_bar = bars["AAPL"]
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.previous_aapl_close is not None:
                change = aapl_close - self.previous_aapl_close
                self.aapl_red_streak = (
                    self.aapl_red_streak + 1 if change < 0 else 0
                )
                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                self.rsi_change_count += 1

                if self.rsi_change_count <= 14:
                    self.rsi_gain_sum += gain
                    self.rsi_loss_sum += loss
                    if self.rsi_change_count == 14:
                        self.rsi_average_gain = self.rsi_gain_sum / 14.0
                        self.rsi_average_loss = self.rsi_loss_sum / 14.0
                else:
                    self.rsi_average_gain = (
                        self.rsi_average_gain * 13.0 + gain
                    ) / 14.0
                    self.rsi_average_loss = (
                        self.rsi_average_loss * 13.0 + loss
                    ) / 14.0

                if self.rsi_change_count >= 14:
                    if self.rsi_average_loss == 0:
                        self.aapl_rsi = 100.0
                    else:
                        relative_strength = (
                            self.rsi_average_gain / self.rsi_average_loss
                        )
                        self.aapl_rsi = 100.0 - 100.0 / (
                            1.0 + relative_strength
                        )
            self.previous_aapl_close = aapl_close

        complete_day = all(bar is not None for bar in bars.values())
        if complete_day:
            self._evaluate_spy(spy_close, spy_sma)
            self._evaluate_aapl(aapl_close)

        if spy_bar is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma

    def _evaluate_spy(self, close, sma):
        if (
            sma is None
            or self.previous_spy_sma is None
            or self.previous_spy_close is None
        ):
            return

        symbol = self.symbols["SPY"]
        invested = self.portfolio[symbol].invested
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )

        if not invested and crosses_above:
            self.set_holdings(symbol, 0.40)
        elif invested and crosses_below:
            self.liquidate(symbol)

    def _evaluate_aapl(self, close):
        symbol = self.symbols["AAPL"]
        invested = self.portfolio[symbol].invested

        if not invested and self.aapl_red_streak >= 3:
            cash = float(self.portfolio.cash)
            if cash >= 20_000:
                quantity = floor(20_000 / close)
                if quantity > 0:
                    self.market_order(symbol, quantity)
        elif invested and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.liquidate(symbol)

