        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_relation = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_relation = None
        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == self.spy_closes.maxlen:
                spy_sma = sum(self.spy_closes) / len(self.spy_closes)
                spy_relation = float(spy_bar.Close) - spy_sma

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_day = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if complete_day:
            self._evaluate_strategy_a(spy, spy_relation)
            self._evaluate_strategy_b(aapl, float(data.Bars[aapl].Close))

        if spy_relation is not None:
            self.spy_previous_relation = spy_relation

    def _evaluate_strategy_a(self, spy, current_relation):
        if current_relation is None or self.spy_previous_relation is None:
            return

        quantity = self.Portfolio[spy].Quantity
        crossed_above = self.spy_previous_relation <= 0 and current_relation > 0
        crossed_below = self.spy_previous_relation >= 0 and current_relation < 0

        if quantity == 0 and crossed_above:
            self.SetHoldings(spy, 0.40)
        elif quantity != 0 and crossed_below:
            self.Liquidate(spy)

    def _evaluate_strategy_b(self, aapl, close):
        if not self.aapl_rsi.IsReady:
            return

        quantity = self.Portfolio[aapl].Quantity
        if quantity == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = floor(20_000 / close)
                if shares > 0:
                    self.MarketOrder(aapl, shares)
        elif quantity != 0 and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(aapl)

