class DailyParallelStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.pending_symbols = set()

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]
        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        previous_aapl_close = self.previous_aapl_close
        if aapl_bar is not None:
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        spy_ready = spy_bar is not None and self.spy_sma.IsReady
        crosses_above = False
        crosses_below = False
        if spy_ready:
            current_spy_sma = self.spy_sma.Current.Value
            if self.previous_spy_close is not None:
                crosses_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_bar.Close > current_spy_sma
                )
                crosses_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_bar.Close < current_spy_sma
                )
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if spy_ready and spy not in self.pending_symbols:
            if not self.Portfolio[spy].Invested and crosses_above:
                tickets = self.SetHoldings(spy, 0.40)
                if tickets:
                    self.pending_symbols.add(spy)
            elif self.Portfolio[spy].Invested and crosses_below:
                tickets = self.Liquidate(spy)
                if tickets:
                    self.pending_symbols.add(spy)

        if self.aapl_rsi.IsReady and aapl not in self.pending_symbols:
            if not self.Portfolio[aapl].Invested:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.pending_symbols.add(aapl)
            elif self.aapl_rsi.Current.Value > 60:
                tickets = self.Liquidate(aapl)
                if tickets:
                    self.pending_symbols.add(aapl)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            open_orders = self.Transactions.GetOpenOrders(orderEvent.Symbol)
            if not open_orders:
                self.pending_symbols.discard(orderEvent.Symbol)

