class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.aapl_red_streak = 0
        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

        # The extra observation permits both sides of the first possible SMA
        # crossing to be fully formed before live rule evaluation begins.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        previous_spy_close = self.previous_closes.get(spy)
        previous_spy_sma = (
            float(self.spy_sma.Current.Value) if self.spy_sma.IsReady else None
        )

        # Market-state quantities consume every bar that is available, even if
        # another subscription is absent and trading rules must be skipped.
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = float(data.Bars[symbol].Close)
            previous_close = self.previous_closes.get(symbol)

            if symbol == spy:
                self.spy_sma.Update(data.Time, close)
            elif symbol == aapl:
                if previous_close is None or close >= previous_close:
                    self.aapl_red_streak = 0
                else:
                    self.aapl_red_streak += 1
                self.aapl_rsi.Update(data.Time, close)

            self.previous_closes[symbol] = close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp:
            return

        spy_close = float(data.Bars[spy].Close)
        spy_sma = float(self.spy_sma.Current.Value)

        if (
            self.strategy_a_quantity == 0
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and self.spy_sma.IsReady
            and previous_spy_close <= previous_spy_sma
            and spy_close > spy_sma
        ):
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_quantity = quantity
        elif (
            self.strategy_a_quantity > 0
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_close < spy_sma
        ):
            self.MarketOrder(spy, -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(20_000 // float(data.Bars[aapl].Close))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_quantity = quantity
        elif (
            self.strategy_b_quantity > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self.MarketOrder(aapl, -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

