class DailySmaAndRsiAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to update whenever their own data exists.
        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            prior_aapl_close = self.previous_closes.get("AAPL")
            if prior_aapl_close is not None and aapl_bar.close < prior_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self.evaluate_strategy_a(bars["SPY"])
            self.evaluate_strategy_b(bars["AAPL"])

        if "SPY" in bars and self.spy_sma.is_ready:
            self.previous_spy_sma = self.spy_sma.current.value
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

    def evaluate_strategy_a(self, bar: TradeBar):
        if not self.spy_sma.is_ready or self.previous_spy_sma is None:
            return

        previous_close = self.previous_closes.get("SPY")
        if previous_close is None:
            return

        symbol = self.symbols["SPY"]
        invested = self.portfolio[symbol].invested
        crossed_above = (
            previous_close <= self.previous_spy_sma
            and bar.close > self.spy_sma.current.value
        )
        crossed_below = (
            previous_close >= self.previous_spy_sma
            and bar.close < self.spy_sma.current.value
        )

        if not invested and not self.spy_order_pending and crossed_above:
            self.spy_order_pending = True
            self.set_holdings(symbol, 0.40)
        elif invested and not self.spy_order_pending and crossed_below:
            self.spy_order_pending = True
            self.liquidate(symbol)

    def evaluate_strategy_b(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready:
            return

        symbol = self.symbols["AAPL"]
        invested = self.portfolio[symbol].invested

        if not invested and not self.aapl_order_pending and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.portfolio.cash >= cash_to_invest:
                quantity = int(cash_to_invest // bar.close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.market_order(symbol, quantity)
        elif (
            invested
            and not self.aapl_order_pending
            and self.aapl_rsi.current.value > 60
        ):
            self.aapl_order_pending = True
            self.liquidate(symbol)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in [OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID]:
            return

        if order_event.symbol == self.symbols["SPY"]:
            self.spy_order_pending = False
        elif order_event.symbol == self.symbols["AAPL"]:
            self.aapl_order_pending = False

