class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_active = False
        self.strategy_b_active = False

    def OnData(self, data):
        spy_bar = data.Bars[self.symbols["SPY"]] if data.Bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = data.Bars[self.symbols["AAPL"]] if data.Bars.ContainsKey(self.symbols["AAPL"]) else None

        spy_sma = None
        spy_crosses_above = False
        spy_crosses_below = False
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0
                if self.spy_previous_close is not None and self.spy_previous_sma is not None:
                    spy_crosses_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and float(spy_bar.Close) > spy_sma
                    )
                    spy_crosses_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and float(spy_bar.Close) < spy_sma
                    )

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values())
        if all_bars_present:
            self._evaluate_strategy_a(spy_bar, spy_crosses_above, spy_crosses_below)
            self._evaluate_strategy_b(aapl_bar)

        if spy_bar is not None:
            self.spy_previous_close = float(spy_bar.Close)
            if spy_sma is not None:
                self.spy_previous_sma = spy_sma
        if aapl_bar is not None:
            self.aapl_previous_close = float(aapl_bar.Close)

    def _evaluate_strategy_a(self, spy_bar, crosses_above, crosses_below):
        if len(self.spy_closes) < 100 or self.spy_previous_sma is None:
            return

        symbol = self.symbols["SPY"]
        if not self.strategy_a_active and crosses_above:
            quantity = self.CalculateOrderQuantity(symbol, 0.40)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.strategy_a_active = True
        elif self.strategy_a_active and crosses_below:
            self.Liquidate(symbol)
            self.strategy_a_active = False

    def _evaluate_strategy_b(self, aapl_bar):
        if not self.aapl_rsi.IsReady:
            return

        symbol = self.symbols["AAPL"]
        if not self.strategy_b_active and self.aapl_red_streak >= 3:
            purchase_value = 20_000
            if float(self.Portfolio.Cash) >= purchase_value:
                quantity = floor(purchase_value / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(symbol, quantity)
                    self.strategy_b_active = True
        elif self.strategy_b_active and float(self.aapl_rsi.Current.Value) > 60:
            self.Liquidate(symbol)
            self.strategy_b_active = False

