class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_relation = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data):
        bars = data.Bars

        spy_crossed_above = False
        spy_crossed_below = False
        if bars.ContainsKey(self.spy):
            spy_close = bars[self.spy].Close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100
                relation = spy_close - spy_sma
                if self.spy_previous_relation is not None:
                    spy_crossed_above = (
                        self.spy_previous_relation <= 0 and relation > 0
                    )
                    spy_crossed_below = (
                        self.spy_previous_relation >= 0 and relation < 0
                    )
                self.spy_previous_relation = relation

        if bars.ContainsKey(self.aapl):
            aapl_close = bars[self.aapl].Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Time, aapl_close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        self._evaluate_spy(spy_crossed_above, spy_crossed_below)
        self._evaluate_aapl(bars[self.aapl].Close)

    def _evaluate_spy(self, crossed_above, crossed_below):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if crossed_below and not self.spy_order_pending:
                self.spy_order_pending = True
                self.Liquidate(self.spy, "Strategy A: close crossed below SMA100")
        elif crossed_above and not self.spy_order_pending:
            self.spy_order_pending = True
            self.SetHoldings(
                self.spy, 0.40, False, "Strategy A: close crossed above SMA100"
            )

    def _evaluate_aapl(self, close):
        quantity = self.Portfolio[self.aapl].Quantity
        if quantity != 0:
            if (
                self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
                and not self.aapl_order_pending
            ):
                self.aapl_order_pending = True
                self.Liquidate(self.aapl, "Strategy B: RSI14 above 60")
        elif self.aapl_red_streak >= 3 and not self.aapl_order_pending:
            if self.Portfolio.Cash >= 20_000:
                order_quantity = floor(20_000 / close)
                if order_quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(
                        self.aapl,
                        order_quantity,
                        False,
                        "Strategy B: three consecutive red days",
                    )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        if order_event.Symbol == self.spy:
            self.spy_order_pending = False
        elif order_event.Symbol == self.aapl:
            self.aapl_order_pending = False

