        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = data.bars

        for symbol in self.symbols.values():
            if bars.contains_key(symbol):
                bar = bars[symbol]
                previous_close = self.previous_closes.get(symbol)

                if symbol == self.aapl and previous_close is not None:
                    if bar.close < previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                if symbol == self.spy:
                    self.spy_sma.update(bar.end_time, bar.close)
                elif symbol == self.aapl:
                    self.aapl_rsi.update(bar.end_time, bar.close)

                self.previous_closes[symbol] = bar.close

        complete_day = all(
            bars.contains_key(symbol) for symbol in self.symbols.values()
        )

        if complete_day:
            self._evaluate_strategy_a(bars[self.spy])
            self._evaluate_strategy_b(bars[self.aapl])

        if bars.contains_key(self.spy) and self.spy_sma.is_ready:
            self.previous_spy_close = bars[self.spy].close
            self.previous_spy_sma = self.spy_sma.current.value

    def _evaluate_strategy_a(self, spy_bar):
        if not self.spy_sma.is_ready:
            return

        current_close = spy_bar.close
        current_sma = self.spy_sma.current.value
        has_previous_values = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )
        if not has_previous_values:
            return

        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and current_close > current_sma
        )
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and current_close < current_sma
        )

        if self.strategy_a_shares == 0 and crossed_above:
            quantity = self.calculate_order_quantity(self.spy, 0.40)
            if quantity > 0:
                self.market_order(self.spy, quantity)
                self.strategy_a_shares = quantity
        elif self.strategy_a_shares > 0 and crossed_below:
            self.market_order(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

    def _evaluate_strategy_b(self, aapl_bar):
        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash = self.portfolio.cash_book["USD"].amount
            if cash >= 20_000:
                quantity = int(20_000 // aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.strategy_b_shares = quantity
        elif (
            self.strategy_b_shares > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

