        tickers = ("SPY", "AAPL", "IBM", "BAC", "AIG")
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = self.SMA(
            self.symbols["SPY"], 100, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.previous_spy_above_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.strategy_a_open = False
        self.strategy_b_open = False

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = bars[spy] if bars.ContainsKey(spy) else None
        aapl_bar = bars[aapl] if bars.ContainsKey(aapl) else None

        spy_above_sma = None
        if spy_bar is not None and self.spy_sma.IsReady:
            spy_above_sma = spy_bar.Close > self.spy_sma.Current.Value

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        complete_day = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady

        if complete_day and indicators_ready and not self.IsWarmingUp:
            crossed_above = (
                self.previous_spy_above_sma is not None
                and not self.previous_spy_above_sma
                and spy_above_sma
            )
            crossed_below = (
                self.previous_spy_above_sma is not None
                and self.previous_spy_above_sma
                and not spy_above_sma
            )

            if not self.strategy_a_open and crossed_above:
                self.SetHoldings(spy, 0.40)
                self.strategy_a_open = self.Portfolio[spy].Invested
            elif self.strategy_a_open and crossed_below:
                self.Liquidate(spy)
                self.strategy_a_open = False

            if not self.strategy_b_open and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.strategy_b_open = self.Portfolio[aapl].Invested
            elif (
                self.strategy_b_open
                and self.aapl_rsi.Current.Value > 60
            ):
                self.Liquidate(aapl)
                self.strategy_b_open = False

        if spy_above_sma is not None:
            self.previous_spy_above_sma = spy_above_sma

