        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.add_equity(
                ticker, Resolution.DAILY, fill_forward=False
            )
            self.symbols[ticker] = security.symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def on_data(self, data: Slice):
        bars = {}
        complete_day = True
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                complete_day = False
                continue
            bar = data.bars[symbol]
            if bar.is_fill_forward:
                complete_day = False
                continue
            bars[ticker] = bar

        spy = bars.get("SPY")
        if spy is not None:
            prior_spy_close = self.previous_spy_close
            prior_spy_sma = self.previous_spy_sma
            self.spy_sma.update(spy.end_time, spy.close)
            current_spy_sma = (
                self.spy_sma.current.value if self.spy_sma.is_ready else None
            )
            self.previous_spy_close = spy.close
            self.previous_spy_sma = current_spy_sma
        else:
            prior_spy_close = None
            prior_spy_sma = None
            current_spy_sma = None

        aapl = bars.get("AAPL")
        if aapl is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl.close
            self.aapl_rsi.update(aapl.end_time, aapl.close)

        if not complete_day:
            return

        spy_symbol = self.symbols["SPY"]
        spy_holding = self.portfolio[spy_symbol]
        spy_cross_data_ready = (
            prior_spy_close is not None
            and prior_spy_sma is not None
            and current_spy_sma is not None
        )
        if spy_cross_data_ready:
            crosses_above = (
                prior_spy_close <= prior_spy_sma
                and spy.close > current_spy_sma
            )
            crosses_below = (
                prior_spy_close >= prior_spy_sma
                and spy.close < current_spy_sma
            )
            if not spy_holding.invested and crosses_above:
                self.set_holdings(spy_symbol, 0.40)
            elif spy_holding.invested and crosses_below:
                self.liquidate(spy_symbol)

        aapl_symbol = self.symbols["AAPL"]
        aapl_holding = self.portfolio[aapl_symbol]
        if (
            not aapl_holding.invested
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = floor(20_000 / aapl.close)
            if quantity > 0:
                self.market_order(aapl_symbol, quantity)
        elif (
            aapl_holding.invested
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.liquidate(aapl_symbol)

