        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_open = False
        self.strategy_b_open = False

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_close = None
        spy_sma = None
        if "SPY" in bars:
            spy_close = bars["SPY"].Close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0

        aapl_close = None
        if "AAPL" in bars:
            aapl_close = bars["AAPL"].Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(data.Time, aapl_close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            self._evaluate_strategy_a(spy_close, spy_sma)
            self._evaluate_strategy_b(aapl_close)

        if spy_close is not None:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma
        if aapl_close is not None:
            self.aapl_previous_close = aapl_close

    def _evaluate_strategy_a(self, close, sma):
        indicators_ready = (
            sma is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close is not None
        )
        if not indicators_ready:
            return

        crossed_above = (
            self.spy_previous_close <= self.spy_previous_sma and close > sma
        )
        crossed_below = (
            self.spy_previous_close >= self.spy_previous_sma and close < sma
        )
        symbol = self.symbols["SPY"]

        if self.strategy_a_open:
            if crossed_below:
                quantity = self.Portfolio[symbol].Quantity
                if quantity != 0:
                    self.MarketOrder(symbol, -quantity)
                self.strategy_a_open = False
        elif crossed_above:
            quantity = self.CalculateOrderQuantity(symbol, 0.40)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.strategy_a_open = True

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.IsReady:
            return

        symbol = self.symbols["AAPL"]
        if self.strategy_b_open:
            if self.aapl_rsi.Current.Value > 60:
                quantity = self.Portfolio[symbol].Quantity
                if quantity != 0:
                    self.MarketOrder(symbol, -quantity)
                self.strategy_b_open = False
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.strategy_b_open = True

