class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # The extra SPY observation permits today's and yesterday's complete
        # 100-day averages to be compared on the same bar.
        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def on_data(self, data: Slice):
        # Market-state quantities continue to advance whenever their own data
        # is present, even when another subscription is absent.
        if data.bars.contains_key(self.spy):
            self.spy_closes.add(float(data.bars[self.spy].close))

        if data.bars.contains_key(self.aapl):
            aapl_bar = data.bars[self.aapl]
            aapl_close = float(aapl_bar.close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols):
            return

        spy_invested = self.portfolio[self.spy].invested
        if self.spy_closes.is_ready:
            spy_close_today = self.spy_closes[0]
            spy_close_yesterday = self.spy_closes[1]
            sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            if not spy_invested:
                if spy_close_yesterday <= sma_yesterday and spy_close_today > sma_today:
                    self.set_holdings(self.spy, 0.40)
            elif spy_close_yesterday >= sma_yesterday and spy_close_today < sma_today:
                self.liquidate(self.spy)

        if self.aapl_rsi.is_ready:
            aapl_invested = self.portfolio[self.aapl].invested
            if not aapl_invested:
                if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                    quantity = int(20_000 // float(data.bars[self.aapl].close))
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
            elif self.aapl_rsi.current.value > 60:
                self.liquidate(self.aapl)

