        if all_bars_present:
            self._evaluate_spy_strategy(spy_bar, spy_sma)
            self._evaluate_aapl_strategy(aapl_bar)

        if spy_bar is not None and spy_sma is not None:
            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_sma = spy_sma
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.Close)

    def _evaluate_spy_strategy(self, bar, sma):
        if (
            sma is None
            or self.previous_spy_close is None
            or self.previous_spy_sma is None
        ):
            return

        close = float(bar.Close)
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        )
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        )
        holding = self.Portfolio[self.symbols["SPY"]]

        if not holding.Invested and crossed_above:
            self.SetHoldings(self.symbols["SPY"], 0.40)
        elif holding.Invested and crossed_below:
            self.Liquidate(self.symbols["SPY"])

    def _evaluate_aapl_strategy(self, bar):
        if not self.aapl_rsi.IsReady:
            return

        symbol = self.symbols["AAPL"]
        holding = self.Portfolio[symbol]
        if not holding.Invested and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = math.floor(20_000 / float(bar.Close))
                if quantity > 0:
                    self.MarketOrder(symbol, quantity)
