class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # One extra SPY close is retained so both sides of a crossing can be
        # evaluated with their respective 100-day averages.
        self.spy_closes = deque(maxlen=101)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        bars = {}
        for symbol in self.symbols:
            if data.bars.contains_key(symbol):
                bars[symbol] = data.bars[symbol]

        # Market-state quantities consume every bar that is available, even
        # when another subscription is missing and trading rules must be skipped.
        if self.spy in bars:
            self.spy_closes.append(float(bars[self.spy].close))

        if self.aapl in bars:
            aapl_close = float(bars[self.aapl].close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.update(bars[self.aapl].end_time, aapl_close)

        if len(bars) != len(self.symbols):
            return

        self._evaluate_spy(float(bars[self.spy].close))
        self._evaluate_aapl(float(bars[self.aapl].close))

    def _evaluate_spy(self, close):
        if len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100.0
        current_sma = sum(closes[1:]) / 100.0
        previous_close = closes[-2]

        crossed_above = previous_close <= previous_sma and close > current_sma
        crossed_below = previous_close >= previous_sma and close < current_sma

        if self.spy_lot_shares == 0 and not self.spy_order_pending and crossed_above:
            self.spy_order_pending = True
            self.set_holdings(self.spy, 0.40)
        elif self.spy_lot_shares > 0 and not self.spy_order_pending and crossed_below:
            self.spy_order_pending = True
            self.market_order(self.spy, -self.spy_lot_shares)

    def _evaluate_aapl(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot_shares == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 // close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.market_order(self.aapl, quantity)
        elif (
            self.aapl_lot_shares > 0
            and not self.aapl_order_pending
            and self.aapl_rsi.current.value > 60
        ):
            self.aapl_order_pending = True
            self.market_order(self.aapl, -self.aapl_lot_shares)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.symbol == self.spy:
            self.spy_lot_shares += int(order_event.fill_quantity)
            if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
                self.spy_order_pending = False
        elif order_event.symbol == self.aapl:
            self.aapl_lot_shares += int(order_event.fill_quantity)
            if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
                self.aapl_order_pending = False

