        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma and bar.Close > sma
        )
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma and bar.Close < sma
        )

        if not self.Portfolio[symbol].Invested:
            if crossed_above and not self.Transactions.GetOpenOrders(symbol):
                quantity = self.CalculateOrderQuantity(symbol, 0.40)
                if quantity > 0:
                    self.MarketOrder(symbol, quantity, tag="Strategy A entry")
        elif crossed_below:
            self.Liquidate(symbol, tag="Strategy A exit")

    def _evaluate_aapl(self, bar):
        symbol = self.symbols["AAPL"]

        if not self.Portfolio[symbol].Invested:
            if self.aapl_red_streak >= 3 and not self.Transactions.GetOpenOrders(symbol):
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // bar.Close)
                    if quantity > 0:
                        self.MarketOrder(symbol, quantity, tag="Strategy B entry")
        elif self.aapl_rsi.Current.Value > 60:
